import { ApiError, UploadAbortedError, type ApiClient } from "./client";
import { DEMO_IDS } from "./demo";
import type {
  AnalysisList,
  AnalysisResult,
  AnalysisStatus,
  AnalysisSummary,
  FramesPayload,
  User,
} from "./types";

/**
 * Backend stand-in for VITE_USE_MOCKS=true. Serves real pipeline output from
 * /public/mock (generated by scripts/make_mock_fixtures.py) and simulates
 * uploads and the worker's stage progression for newly created analyses.
 * A file whose name contains "fail" fails with NO_PERSON_DETECTED.
 * It starts signed in as MOCK_USER so demos open straight to the app; signing
 * out and in again works in memory with any email and password. New sign-ups
 * start unverified; the token "valid" verifies or resets, anything else is expired.
 */

export const MOCK_USER: User = {
  id: "mock-user",
  email: "demo@serve-analyzer.dev",
  created_at: "2026-09-20T10:00:00Z",
  email_verified: true,
};

const TEMPLATE_ID = "demo-serve-1";

export const MOCK_STAGES: { status: AnalysisStatus; ms: number }[] = [
  { status: "queued", ms: 1000 },
  { status: "extracting_pose", ms: 3000 },
  { status: "analyzing", ms: 1000 },
  { status: "rendering", ms: 1500 },
];

interface Created {
  summary: AnalysisSummary;
  startedAt: number | null;
  failing: boolean;
}

export interface MockOptions {
  now?: () => number;
  latencyMs?: number;
  fetchJson?: <T>(path: string) => Promise<T>;
}

async function defaultFetchJson<T>(path: string): Promise<T> {
  const res = await fetch(path);
  if (!res.ok) throw new ApiError(res.status, `Mock fixture ${path} not found`);
  return (await res.json()) as T;
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

export function createMockClient(options: MockOptions = {}): ApiClient {
  const now = options.now ?? Date.now;
  const latency = options.latencyMs ?? 250;
  const fetchJson = options.fetchJson ?? defaultFetchJson;
  const created = new Map<string, Created>();
  let counter = 0;
  let user: User | null = MOCK_USER;
  const deleted = new Set<string>();

  const delay = () => (latency > 0 ? sleep(latency) : Promise.resolve());

  function isDemo(id: string): boolean {
    return (DEMO_IDS as readonly string[]).includes(id);
  }

  function current(entry: Created): AnalysisSummary {
    const { summary, startedAt, failing } = entry;
    if (startedAt === null || summary.status === "failed" || summary.status === "succeeded") {
      return summary;
    }
    let elapsed = now() - startedAt;
    for (const stage of MOCK_STAGES) {
      if (elapsed < stage.ms) return { ...summary, status: stage.status };
      if (failing && stage.status === "extracting_pose") {
        entry.summary = {
          ...summary,
          status: "failed",
          error: {
            code: "NO_PERSON_DETECTED",
            message: "We couldn't detect a person clearly. Check the filming guide.",
          },
        };
        return entry.summary;
      }
      elapsed -= stage.ms;
    }
    entry.summary = {
      ...summary,
      status: "succeeded",
      thumbnail_url: `/mock/${TEMPLATE_ID}/thumbnail.jpg`,
      counts: { good: 3, borderline: 2, off: 0, unknown: 5 },
    };
    return entry.summary;
  }

  function entryOrThrow(id: string): Created {
    const entry = created.get(id);
    if (!entry) throw new ApiError(404, "Analysis not found");
    return entry;
  }

  function assertSucceeded(id: string): void {
    if (isDemo(id)) return;
    const status = current(entryOrThrow(id)).status;
    if (status !== "succeeded") throw new ApiError(409, `Analysis is ${status}`);
  }

  return {
    async getMe() {
      await delay();
      return user;
    },

    async signUp({ email }) {
      await delay();
      user = {
        ...MOCK_USER,
        email: email.trim().toLowerCase(),
        created_at: new Date(now()).toISOString(),
        email_verified: false,
      };
      return user;
    },

    async logIn({ email }) {
      await delay();
      user = { ...MOCK_USER, email: email.trim().toLowerCase() };
      return user;
    },

    async logOut() {
      await delay();
      user = null;
    },

    async verifyEmail(token) {
      await delay();
      if (token !== "valid") throw new ApiError(400, "This link is invalid or has expired. Request a new one.");
      if (user) user = { ...user, email_verified: true };
    },

    async resendVerification() {
      await delay();
    },

    async requestPasswordReset() {
      await delay();
    },

    async resetPassword(token) {
      await delay();
      if (token !== "valid") throw new ApiError(400, "This link is invalid or has expired. Request a new one.");
      user = null;
    },

    async deleteAccount(password) {
      await delay();
      if (!password) throw new ApiError(403, "Incorrect password.");
      user = null;
      created.clear();
    },

    async deleteAnalysis(id) {
      await delay();
      if (!created.delete(id) && !isDemo(id)) throw new ApiError(404, "Analysis not found");
      deleted.add(id);
    },

    async createAnalysis(body) {
      await delay();
      counter += 1;
      const id = `mock-${counter}`;
      const ts = new Date(now()).toISOString();
      const summary: AnalysisSummary = {
        id,
        hand: body.hand,
        status: "awaiting_upload",
        filename: body.filename,
        created_at: ts,
        updated_at: ts,
        error: null,
        thumbnail_url: null,
        counts: null,
      };
      created.set(id, { summary, startedAt: null, failing: /fail/i.test(body.filename) });
      return {
        analysis: summary,
        upload: {
          url: `mock://upload/${id}`,
          method: "PUT",
          headers: { "Content-Type": body.content_type },
          expires_at: new Date(now() + 15 * 60_000).toISOString(),
        },
      };
    },

    async uploadVideo(_target, file, onProgress, signal) {
      const steps = 20;
      const totalMs = Math.min(3000, 800 + file.size / 50_000);
      for (let i = 1; i <= steps; i++) {
        if (signal?.aborted) throw new UploadAbortedError();
        await sleep(totalMs / steps);
        onProgress(i / steps);
      }
    },

    async startAnalysis(id) {
      await delay();
      const entry = entryOrThrow(id);
      if (entry.summary.status !== "awaiting_upload") {
        throw new ApiError(409, `Analysis is already ${entry.summary.status}`);
      }
      entry.startedAt = now();
      entry.summary = { ...entry.summary, status: "queued" };
      return current(entry);
    },

    async retryAnalysis(id) {
      await delay();
      const entry = entryOrThrow(id);
      if (current(entry).status !== "failed") {
        throw new ApiError(409, "Only failed analyses can be retried");
      }
      entry.failing = false;
      entry.startedAt = now();
      entry.summary = { ...entry.summary, status: "queued", error: null };
      return current(entry);
    },

    async getAnalysis(id) {
      await delay();
      if (deleted.has(id)) throw new ApiError(404, "Analysis not found");
      if (isDemo(id)) return fetchJson<AnalysisSummary>(`/mock/${id}/summary.json`);
      return current(entryOrThrow(id));
    },

    async listAnalyses() {
      await delay();
      const fixtures = await fetchJson<AnalysisList>("/mock/analyses.json");
      const mine = [...created.values()].map(current).reverse();
      const demos = fixtures.items.filter((a) => !deleted.has(a.id));
      return { items: [...mine, ...demos], next_cursor: null };
    },

    async getResult(id) {
      await delay();
      assertSucceeded(id);
      const result = await fetchJson<AnalysisResult>(
        `/mock/${isDemo(id) ? id : TEMPLATE_ID}/result.json`,
      );
      return { ...result, id };
    },

    async getFrames(id) {
      await delay();
      assertSucceeded(id);
      return fetchJson<FramesPayload>(`/mock/${isDemo(id) ? id : TEMPLATE_ID}/frames.json`);
    },
  };
}
